SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


/*

EXEC [dbo].[DI_USP_GetAttestationEntitlementByTaskid] 268753



*/
CREATE PROCEDURE [dbo].[DI_USP_GetAttestationEntitlementByTaskid]
    @taskId bigint,
	@endpointSystemId bigint = 0
AS
BEGIN
SET NOCOUNT ON;

	IF EXISTS(SELECT 1 FROM DI_M_Task where Id = @taskId AND ACTION = 1)
	BEGIN

		SELECT
		DISTINCT 
			atttestationSnapShot.Entity AS Entity,
			atttestationSnapShot.Entity AS KeyId,atttestationSnapShot.Level
		FROM DI_M_AttestationSnapshotAction snapShotAction
		JOIN DI_M_AttestationSnapshotActionInterim snapShotActionInterim
		ON snapShotAction.Id = snapShotActionInterim.AttestationSnapshotActionId
		JOIN DI_M_AttestationSnapshot atttestationSnapShot
		ON snapShotAction.AttestationSnapshotId = atttestationSnapShot.Id
		JOIN DI_M_Task approverTask
		ON  snapShotAction.TaskId = approverTask.Id
		JOIN DI_M_AttestationCampaign attetsationCampaign
		on atttestationSnapShot.AttestationCampaignId = attetsationCampaign.Id
		WHERE approverTask.Id = @taskId AND atttestationSnapShot.Level > 1 AND ((@endpointSystemId  > 0  AND atttestationSnapShot.EndpointId = @endpointSystemId ) OR @endpointSystemId  = 0) 
		AND atttestationSnapShot.AccountType = 1
		ORDER BY atttestationSnapShot.Entity

	END
	ELSE
	BEGIN
		 
		SELECT 
			atttestationSnapShot.Entity AS Entity,
			atttestationSnapShot.Entity AS KeyId,atttestationSnapShot.Level
		FROM DI_M_AttestationSnapshotAction_History snapShotHistory
		JOIN DI_M_AttestationSnapshotAction snapShotAction
		ON snapShotHistory.AttestationSnapshotActionId = snapShotAction.Id
		JOIN DI_M_AttestationSnapshot atttestationSnapShot
		ON snapShotAction.AttestationSnapshotId = atttestationSnapShot.Id
		JOIN DI_M_Task approverTask
		ON  snapShotHistory.TaskId = approverTask.Id
		JOIN DI_M_AttestationCampaign attetsationCampaign
		ON atttestationSnapShot.AttestationCampaignId = attetsationCampaign.Id
		WHERE approverTask.Id = @taskId AND atttestationSnapShot.Level > 1 AND ((@endpointSystemId  > 0  AND atttestationSnapShot.EndpointId = @endpointSystemId ) OR @endpointSystemId  = 0)
		AND atttestationSnapShot.AccountType = 1
		ORDER BY atttestationSnapShot.Entity



	END
END


GO

